without_definite_outcome.query:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?painting ?paintingLabel ?creator ?creatorLabel WHERE {
  ?painting wdt:P31 wd:Q3305213 .
  ?painting wdt:P180 wd:Q7721 .
  OPTIONAL { ?painting wdt:P170 ?creator . }

 OPTIONAL { ?creator rdfs:label ?creatorLabel . FILTER (LANG(?creatorLabel) = "en") } OPTIONAL { ?painting rdfs:label ?paintingLabel . FILTER (LANG(?paintingLabel) = "en") } }
